insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 27, 'E pelo Espírito foi ao Templo; e quando os pais trouxeram o menino Jesus, para fazerem com ele conforme o costume da Lei,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 28, 'Então ele o tomou em seus braços, louvou a Deus, e disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 29, 'Agora, Senhor, despedes o teu servo em paz, conforme a tua palavra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 30, 'pois os meus olhos viram a tua salvação,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 31, 'a qual preparaste diante de todos os povos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 32, 'Luz para iluminar as gentios, e para a glória do teu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 33, 'E José e sua mãe se admiraram das coisas que se diziam sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 34, 'Simeão os abençoou, e disse a Maria, sua mãe: Eis que este é posto para queda e levantamento de muitos em Israel; e para sinal que terá oposição,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 35, '(também uma espada atravessará a tua própria alma) para que os pensamentos de muitos corações se manifestem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 36, 'E estava ali a profetiza Ana, filha de Fanuel, da tribo de Aser. Ela já tinha idade avançada, e havia vivido com o marido sete anos desde sua virgindade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 37, 'E era viúva de cerca de oitenta e quatro anos, e não se afastava do Templo, servindo [a Deus] com jejuns e orações, de noite e de dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 38, 'E ela veio na mesma hora; ela agradeci ao Senhor, e falava dele a todos os que esperavam a redenção em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 39, 'E quando acabaram de cumprir tudo, segundo a Lei do Senhor, voltaram à Galileia, para a sua cidade de Nazaré.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 40, 'E o menino crescia e se fortalecia em espírito, e cheio de sabedoria; e a graça de Deus estava sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 41, 'Todos os anos, seus pais iam a Jerusalém, para a festa da Páscoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 42, 'E quando [Jesus] tinha doze anos, subiram a Jerusalém, conforme o costume do festival;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 43, 'E quando aqueles dias terminaram, eles partiram de volta, mas o menino Jesus ficou em Jerusalém sem que José e sua mãe soubessem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 44, 'Porém, como pensavam que ele vinha pelo caminho entre os companheiros de viagem, eles andaram o caminho de um dia; e o procuraram entre os parentes e conhecidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 45, 'E como não o acharam, voltaram a Jerusalém em busca dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 46, 'E aconteceu que, três dias depois, o acharam no templo, sentado no meio dos mestres, ouvindo-os, e perguntando-lhes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 47, 'E todos os que o ouviam admiravam a sua inteligência e respostas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 48, 'Quando eles o viram, ficarm surpresos. E sua mãe lhe disse: Filho, por que fizeste assim conosco? Eis que teu pai e eu com ansiedade te procurávamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 49, 'Ele lhes disse: Por que me procuráveis? Não sabeis que devo estar nos negócios de meu Pai?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 50, 'E eles não entenderam as palavras que lhes dizia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 51, 'Então desceu com eles, e veio a Nazaré, e os obedecia. E a sua mãe guardava todas essas coisas no seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 52, 'Jesus crescia em sabedoria, em estatura, e em graça para com Deus e as pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 1, 'No ano quinze do império de Tibério César, sendo Pôncio Pilatos o governador da Judeia, Herodes tetraca da Galileia, e seu irmão Filipe o tetrarca da Itureia e da província de Traconites, e Lisânias o tetrarca de Abilene;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 2, 'sendo Anás e Caifás os sumos sacerdotes, a palavra de Deus veio a João, filho de Zacarias, no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 3, 'Ele percorreu toda a região ao redor do Jordão, pregando o batismo de arrependimento, para o perdão dos pecados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 4, 'conforme o que está escrito no livro das palavras do profeta Isaías, que diz: “Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 5, 'Todo vale se encherá, e todo monte e colina se abaixará; os tortos serão endireitados, e os caminhos ásperos se suavizarão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 6, 'e todos verão a salvação de Deus.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 7, '[João] dizia às multidões que vinham ser batizadas por ele: “Raça de víboras, quem vos ensinou a fugir da ira que está para chegar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 8, 'Dai, pois, frutos condizentes com o arrependimento, e não comeceis a dizer em vós mesmos: ‘Temos Abraão por pai’; pois eu vos digo que até destas pedras Deus pode produzir filhos a Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 9, 'E também o machado já está posto à raiz das árvores; portanto, toda árvore que não dá bom fruto é cortada e lançada ao fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 10, 'E as multidões lhe perguntavam: Então o que devemos fazer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 11, 'E ele lhes respondeu: Quem tiver duas túnicas, reparta com o não tem; e quem tiver comida, faça da mesma maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 12, 'E chegaram também uns publicanos, para serem batizados; e disseram-lhe: Mestre, que devemos fazer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 13, 'E ele lhes disse: Não exijais mais do que vos está ordenado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 14, 'E uns soldados também lhe perguntaram: E nós, que devemos fazer? E ele lhes disse: Não maltrateis nem defraudeis a ninguém; e contentai-vos com vossos salários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 15, 'E, enquanto o povo estava em expectativa, e todos pensando em seus corações se talvez João seria o Cristo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 16, 'João respondeu a todos: De fato, eu vos batizo com água, mas vem um que é mais poderoso do que eu, de quem eu não sou digno de desatar a tira das sandálias; ele vos batizará com o Espírito Santo e com fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 17, 'Sua pá está na sua mão, e limpará sua eira, e juntará o trigo no seu celeiro; porém queimará a palha com fogo que nunca se apaga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 18, 'Assim, exortando com muitas outras coisas, [João] anunciava a boa notícia ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 19, 'Porém, quando Herodes, o tetrarca, foi repreendido por ele por causa de Herodias, mulher do seu irmão Filipe, e por todas as maldades que Herodes havia feito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 20, 'acrescentou a todas ainda esta: encarcerou João na prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 21, 'E aconteceu que, quando todo o povo era batizado, Jesus [também] foi batizado, e enquanto orava, o céu se abriu,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 22, 'e o Espírito Santo desceu sobre ele em forma corpórea, como pomba; e veio do céu uma voz que dizia: Tu és o meu Filho amado, em ti me agrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 23, 'E o mesmo Jesus começou quando tinha cerca de trinta anos, sendo (como se pensava) filho de José, [filho] de Eli,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 24, '[filho] de Matate, [filho] de Levi, [filho] de Melqui, [filho] de Janai, [filho] de José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 25, '[filho] de Matatias, [filho] de Amós, [filho] de Naum, [filho] de Esli, [filho] de Nagai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 26, '[filho] de Maate, [filho] de Matatias, [filho] de Semei, [filho] de José, [filho] de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 27, '[filho] de Joaná, [filho] de Resa, [filho] de Zorobabel, e [filho] de Salatiel, [filho] de Neri.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 28, '[filho] de Melqui, [filho] de Adi, e [filho] de Cosã, [filho] de Elmodã, [filho] de Er.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 29, '[filho] de José,[filho] de Eliézer, [filho] de Jorim, [filho] de Matate, [filho] de Levi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 30, '[filho] de Simeão, [filho] de Judá, [filho] de José, [filho] de Jonã, [filho] de Eliaquim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 31, '[filho] de Meleá, [filho] de Mainã, [filho] de Matatá, [filho] de Natã, [filho] de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 32, '[Filho] de Jessé, [filho] de Obede, [filho] de Boaz, [filho] de Salmom, [filho] de Naassom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 33, '[Filho] de Aminadabe, [filho] de Arão,[filho] de Esrom, [filho] de Peres, [filho] de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 34, '[filho] de Jacó, [filho] de Isaque, [filho] de Abraão, [filho] de Terá, [filho] de Naor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 35, '[filho] de Serugue, [filho] de Ragaú, [filho] de Faleque, [filho] de Éber, [filho] de Salá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 36, '[Filho] de Cainã, [filho] de Arfaxade, [filho] de Sem, [filho] de Noé, [filho] de Lameque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 37, '[Filho] de Matusalém, [filho] de Enoque, [filho] de Jarede, [filho] de Maleleel, [filho] de Cainã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 3, 38, '[filho] de Enos, [filho] de Sete, [filho] de Adão, [e Adão] de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 1, 'E Jesus, cheio do Espírito Santo, voltou do Jordão, e foi levado pelo Espírito ao deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 2, 'E por quarenta dias foi tentado pelo diabo; e não comeu coisa alguma naqueles dias; e terminados eles, depois teve fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 3, 'Então o diabo lhe disse: Se tu és Filho de Deus, diz a esta pedra que se transforme em pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 4, 'Jesus lhe respondeu: Está escrito que não só de pão viverá o ser humano, mas de toda palavra de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 5, 'E o diabo o levou a um alto monte, e lhe mostrou todos os reinos do mundo num instante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 6, 'E o diabo lhe disse: Darei a ti todo este poder e sua glória; pois a mim foram entregues, e os dou a quem quero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 7, 'Portanto, se tu me adorares, tudo será teu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 8, 'E Jesus lhe respondeu: Para trás de mim, Satanás!Porque está escrito: Adorarás ao Senhor teu Deus, e só a ele servirás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 9, 'Então o levou a Jerusalém, e o pôs sobre a parte mais alta do templo, e disse-lhe: Se tu és o Filho de Deus, lança-te daqui abaixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 10, 'Porque está escrito que: Mandará aos seus acerca de ti que te guardem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 11, 'E que: te sustentarão pelas mãos, para que nunca tropeces com o teu pé em alguma pedra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 12, 'Jesus lhe respondeu: Dito está: Não tentes ao Senhor teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 13, 'E quando o diabo acabou toda a tentação, ausentou-se dele por algum tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 14, 'Então Jesus, no poder do Espírito, voltou para a Galileia, e sua fama se espalhou por toda a região ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 15, 'Ele ensinava em suas sinagogas, e era recebido com honra por todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 16, 'Ele foi a Nazaré, onde havia sido criado, e entrou, conforme o seu costume, num dia de Sábado, na sinagoga; e levantou-se para ler.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 17, 'Foi-lhe dado o livro do profeta Isaías; e quando abriu o livro, achou o lugar onde estava escrito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 18, 'O Espírito do Senhor [está] sobre mim, porque ele me ungiu para evangelizar os pobres, me enviou para curar os contritos de coração;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 19, 'para proclamar liberdade aos cativos e dar vista aos cegos, para pôr em liberdade os oprimidos, para proclamar o ano agradável do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 20, 'Ele fechou o livro, e devolveu-o ao assistente, e se sentou. Os olhos de todos na sinagoga estavam fixos nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 21, 'Então ele começou a lhes dizer: Hoje esta escritura se cumpriu em vossos ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 22, 'E todos davam testemunho dele, e se admiravam das palavras graciosas que saíam da sua boca; e diziam: Não é este o filho de José?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 23, 'E ele lhes disse: Sem dúvida me direis este provérbio: Médico, cura a ti mesmo; faz também aqui na tua terra natal todas as coisas que ouvimos terem sido feitas em Cafarnaum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 24, 'E disse: Em verdade vos digo que nenhum profeta é bem recebido na sua terra natal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 25, 'Porém em verdade vos digo que hava muitas viúvas em Israel nos dias de Elias, quando o céu se fechou por três anos e seis meses, de modo que em toda [aquela] terra houve grande fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 26, 'Mas a nenhuma delas Elias foi enviado, a não ser a uma mulher viúva de Sarepta de Sidom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 27, 'E havia muitos leprosos em Israel no tempo do profeta Eliseu; mas nenhum deles foi limpo, a não ser Naamã, o sírio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 28, 'E todos na sinagoga, quando ouviram essas coisas, encheram-se de ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 29, 'Então se levantaram, expulsaram-no da cidade, e o levaram até o topo do monte em que sua cidade era construída, para dali o lançarem abaixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 30, 'Porém ele passou por meio deles, e se retirou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 31, 'Ele desceu a Cafarnaum, cidade de Galileia; e [ali] os ensinava nos sábados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 32, 'E admiravam o seu ensino, pois a sua palavra era com autoridade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 33, 'E estava na sinagoga um homem que tinha um espírito de um demônio imundo, e gritou com alta voz,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 34, 'dizendo: Ah, que temos contigo, Jesus Nazareno? Vieste para nos destruir? Sei quem és: o Santo de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 35, 'E Jesus o repreendeu, dizendo: Cala-te, e, sai dele. E o demônio o derrubou no meio [do povo] , e saiu dele sem lhe fazer dano algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 36, 'E espanto veio sobre todos; e falavam entre si uns aos outros, dizendo: Que palavra é esta, que até aos espíritos imundos ele manda com autoridade e poder, e eles saem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 37, 'E sua fama era divulgada em todos os lugares em redor daquela região.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 38, '[Jesus] levantou-se da sinagoga, e entrou na casa de Simão. A sogra de Simão estava doente de uma grande febre, e rogaram-lhe por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 39, 'Ele se inclinou a ela, e repreendeu a febre, que a deixou. Ela imediatamente se levantou e começou a lhes servir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 40, 'Quando o sol estava se pondo, troxeram-lhe todos os que estavam enfermos de varias doenças. Ele punha as mãos sobre cada um deles e os curava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 41, 'E também de muitos saíam demônios, gritando, e dizendo: Tu és o Cristo, o Filho de Deus. Ele os repreendia, e não os deixava falar, porque sabiam que ele era o Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 42, 'E sendo já dia, ele saiu, e foi a um lugar deserto. As multidões o buscavam; então vieram a ele, e queriam detê-lo, para que não os deixasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 43, 'Porém ele lhes disse: Também é necessário que eu anuncie a outras cidades o evangelho do Reino de Deus; pois para isso sou enviado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 4, 44, 'E ele pregava nas sinagogas da Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 1, 'E aconteceu que as multidões o comprimiam para ouvir a palavra de Deus, quando ele estava junto ao lago de Genesaré.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 2, 'Então ele viu dois barcos que estavam próximos [da margem] do lago, e os pescadores haviam descido deles, e estavam lavando as redes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 3, 'Ele entrou num daqueles barcos, que era o de Simão, e lhe pediu que o afastasse um pouco da terra. Depois se sentou, e do barco ensinou às multidões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 4, 'Quando acabou de falar, disse a Simão: Vai à água profunda, e lançai as vossas redes para pescar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 5, 'Simão lhe respondeu: Mestre, trabalhamos toda a noite, mas nada pegamos; mas pela tua palavra lançarei a rede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 6, 'Eles fizeram assim, e recolheram grande quantidade de peixes, e sua rede estava se rompendo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 7, 'Então acenaram aos companheiros que estavam no outro barco, para que viessem os ajudar. Vieram, e encheram ambos os barcos, de tal maneira que quase afundavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 8, 'Quando Simão Pedro viu[isso] , prostrou-se aos pés de Jesus, dizendo: Afasta-te de mim, Senhor, porque sou um homem pecador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 9, 'Pois ele estava cheio de espanto, como todos os que estavam com ele, por causa da coleta de peixes que haviam feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 10, 'E semelhantemente, também, Tiago e João, filhos de Zebedeu, que eram colegas de Simão. E Jesus disse a Simão: Não temas, de agora em diante pescarás gente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 11, 'Eles levaram os barcos para a terra, deixaram tudo, e o seguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 12, 'E aconteceu que, quando ele estava numa daquelas cidades, eis que um homem cheio de lepra viu Jesus; então prostrou-se sobre o rosto, e lhe rogou, dizendo: Senhor, se quiseres, podes me tornar limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 13, 'Ele estendeu a mão, e o tocou, dizendo: Quero; sê limpo. E logo a lepra desapareceu dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 14, 'E mandou-lhe que não o dissesse a ninguém: Mas vai, mostra-te ao sacerdote, e oferece por tua purificação, como Moisés mandou, para lhes dar testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 15, 'Porém a sua fama se espalhava ainda mais; e ajuntavam-se muitas multidões para o ouvir, e para serem por ele curadas de suas enfermidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 16, 'Porém ele se retirava para os desertos, e [ali] orava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 17, 'E aconteceu num daqueles dias que estava ensinando, e estavam [ali] sentados fariseus e instrutores da lei, que tinham vindo de todas as aldeias da Galileia, da Judeia, e de Jerusalém; e o poder do Senhor estava [ali] para os curar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 18, 'E eis que uns homens traziam numa cama um homem que estava paralítico; e procuravam levá-lo para dentro, a fim de o porem diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 19, 'Como não acharam por onde pudessem levá-lo para dentro, por causa da multidão, subiram ao telhado, e pelas telhas o baixaram com o leito para o meio [do povo] , diante de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 20, 'Ele viu a fé deles, e disse-lhe: Homem, teus pecados são perdoados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 21, 'E os escribas e os fariseus começaram a questionar, dizendo: Quem é este que fala blasfêmias? Quem pode perdoar pecados, senão só Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 22, 'Porém Jesus, conhecendo os seus pensamentos, respondeu-lhes: O que pensais em vossos corações?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 23, 'O que é mais fácil? Dizer: Teus pecados são perdoados? Ou dizer: Levanta-te, e anda?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 24, 'Para que saibais que o Filho do homem tem poder sobre a terra para perdoar pecados, (disse ao paralítico:) Eu te digo, levanta-te, toma o teu leito, e vai para a tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 25, 'E ele levantou-se imediatamente diante deles, tomou o [leito] em que estava deitado, e foi para a sua casa, glorificando a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 26, 'E todos ficaram admirados, e glorificaram a Deus; e ficaram cheios de temor, dizendo: Hoje vimos maravilhas!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 27, 'Depois destas coisas, ele saiu; e viu um publicano, chamado Levi, sentado na coletoria de tributos, e disse-lhe: Segue-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 28, 'Ele deixou tudo, levantou-se, e o seguiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 29, 'E Levi lhe fez um grande banquete em sua casa; e havia [ali] uma grande multidão de publicanos e de outros que estavam sentados com eles [à mesa] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 30, 'E seus escribas e fariseus murmuravam contra os seus discípulos, dizendo: Por que comeis e bebeis com publicanos e pecadores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 31, 'Jesus lhes respondeu: Os que estão sãos não precisam de médico, mas sim os que estão doentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 32, 'Eu não vim para chamar os justos, mas sim, os pecadores, ao arrependimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 33, 'Então eles lhe disseram: Por que os discípulos de João jejuam muitas vezes, e fazem orações, como também os dos fariseus, mas os teus comem e bebem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 34, 'Mas ele lhes disse: Podeis vós fazer jejuar os convidados do casamento, enquanto o noivo está com eles?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 35, 'Porém virão dias em que o esposo lhes será tirado; então naqueles dias jejuarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 36, 'E dizia-lhes também uma parábola: Ninguém põe remendo de pano novo em roupa velha; de outra maneira, o novo rompe, e o remendo do novo não será adequado ao velho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 37, 'E ninguém põe vinho novo em odres velhos; de outra maneira, o vinho novo romperá os odres, e se derramará, e os odres são destruídos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 38, 'Mas o vinho novo deve ser posto em odres novos, e ambos se conservam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 5, 39, 'E ninguém que beber do velho quer logo o novo; porque diz: O velho é melhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 1, 'E aconteceu que, no segundo sábadodepois do primeiro, [Jesus] passou pelas plantações, e seus discípulos iam arrancando espigas, e comiam, debulhando-as com as mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 2, 'E alguns dos fariseus lhes disseram: Por que fazeis o que não é lícito fazer nos sábados?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 3, 'E Jesus lhes respondeu: Nunca lestes isto, o que Davi fez quando teve fome, ele e os que com ele estavam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 4, 'Como entrou na casa de Deus, tomou, e comeu os pães da apresentação, e deu também aos que estavam com ele, [pães] que não é lícito comer, a não ser só os sacerdotes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 5, 'E dizia-lhes: O Filho do homem é Senhor até do sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 6, 'E aconteceu também em outro sábado que entrou na sinagoga, e estava ensinado; e ali estava um homem que tinha a mão direita definhada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 7, 'E os escribas e fariseus o observavam, se o curaria no sábado; para acharem de que o acusar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 8, 'Mas ele bem sabia dos seus pensamentos; e disse ao homem que tinha a mão definhada: Levanta-te, e põe-te em pé no meio. E ele se levantou e se pôs de pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 9, 'Então Jesus lhes disse: Uma coisa vos perguntarei: É lícito nos sábados fazer bem, ou fazer mal? Salvar uma pessoa, ou matá-la?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 10, 'E ele, olhando para todos em redor, disse ao homem: Estende a tua mão. E ele assim o fez; e a mão foi lhe restituída sã como a outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 11, 'Então encheram-se de ira; e conversaram uns com os outros [sobre] o que fariam a Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 12, 'E aconteceu que naqueles dias ele foi ao monte para orar; e passou a noite orando a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 13, 'E quando já era dia, chamou a si os seus discípulos, e escolheu doze deles, a quem também chamou de apóstolos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 14, 'Simão, a quem também chamou de Pedro, e seu irmão André; Tiago, e João; Filipe, e Bartolomeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 15, 'Mateus, Tomé; Tiago [filho] de Alfeu, e Simão chamado “o Zelote”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 16, 'Judas de Tiago, e Judas Iscariotes, o mesmo que foi o traidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 17, 'Ele desceu com eles, parou num lugar plano, e também [com ele] uma grande quantidade dos seus discípulos, e grande multidão do povo de toda a Judeia, de Jerusalém, da costa marítima de Tiro, e de Sidom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 18, 'que tinham vindo para o ouvir, e para serem curados das suas enfermidades, como também os atormentados por espíritos imundos; e foram curados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 19, 'E toda a multidão procurava tocá-lo; porque dele saía poder, e curava a todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 20, 'Ele levantou os olhos aos seus discípulos, e disse: Benditos sois vós, os pobres, porque o Reino de Deus é vosso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 21, 'Benditos sois vós que agora tendes fome, porque sereis saciados. Benditos sois vós que agora chorais, porque rireis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 22, 'Benditos sereis quando as pessoas vos odiarem, quando vos separarem, vos insultarem, e rejeitarem o vosso nome como mau, por causa do Filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 23, 'Contentai-vos nesse dia, e saltai de alegria, porque eis que grande é a vossa recompensa nos céus; pois assim os pais deles faziam aos profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 24, 'Mas ai de vós, ricos, porque já tendes a vossa consolação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 25, 'Ai de vós que estais saciados, porque tereis fome. Ai de vós que agora rides, porque lamentareis, e chorareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 26, 'Ai de vós quando todas as pessoas falarem bem de vós; porque assim os pais deles faziam aos falsos profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 27, 'Mas a vós, que estais ouvindo, digo: amai os vossos inimigos; fazei bem aos que vos odeiam;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 28, 'bendizei aos que vos maldizem, e orai pelos que vos maltratam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 29, 'Ao que te ferir numa face, oferece-lhe também a outra; e ao que te tirar a capa, não recuses a túnica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 30, 'Dá a quem te pedir; e ao que te tomar o [que é] teu, não o peças de volta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 31, 'E como vós quereis que as pessoas vos façam, fazei-lhes vós também da mesma maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 32, 'E se amardes aos que vos amam, que mérito tereis? Pois também os pecadores amam os que os amam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 33, 'E se fizerdes bem aos que vos fazem bem, que mérito tereis? Pois também os pecadores fazem o mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 34, 'E se emprestardes àqueles de quem esperais receber de volta, que mérito tereis? Pois também os pecadores emprestam aos pecadores, para receberam de volta o tanto equivalente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 35, 'Em vez disso, amai aos vossos inimigos, fazei o bem, e emprestai, sem nada esperar disso; e grande será a vossa recompensa, e sereis filhos do Altíssimo; porque é benigno [até] para com os ingratos e maus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 36, 'Portanto, sede misericordiosos, como também o vosso Pai é misericordioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 37, 'Não julgueis, e não sereis julgados; não condeneis, e não sereis condenados; liberai, e vos liberarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 38, 'Dai, e será vos dado; medida boa, comprimida, sacudida e transbordante vos darão no vosso colo; pois com a mesma medida que medirdes vos medirão de volta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 39, 'E disse-lhesuma parábola: Acaso pode o cego guiar [outro] cego? Não cairão ambos no buraco?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 40, 'O discípulo não está acima do seu mestre; mas todo aquele que estiver completamente capacitado será como o seu mestre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 41, 'E por que tu prestas atenção no cisco que está no olho do teu irmão, e não enxergas a trave que está no teu próprio olho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 42, 'Ou como podes dizer a teu irmão: “Irmão, deixa-me tirar o cisco que está no teu olho”, se tu mesmo não prestas atenção na trave que está no teu olho? Hipócrita, tira primeiro a trave de teu olho, e então verás bem para tirar o cisco que está no olho do teu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 43, 'Pois não há boa árvore que dê mau fruto, nem árvore má que dê bom fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 44, 'Porque cada árvore se conhece pelo seu próprio fruto; pois não se colhem figos dos espinheiros, nem se tiram uvas dos cardos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 45, 'A boa pessoa tira o bem do bom tesouro do seu coração, e a pessoa má tira o mal do mau tesouro do seu coração; pois a sua boca fala daquilo que o coração tem em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 46, 'E por que me chamais: “Senhor!”, “Senhor!”, e não fazeis o que eu digo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 47, 'Todo aquele que vem a mim, ouve as minhas palavras, e as pratica, eu vos mostrarei a quem é semelhante:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 48, 'Semelhante é ao homem que construiu uma casa, cavou, abriu bem fundo, e pôs o fundamento sobre a rocha; e quando veio a enchente, a corrente bateu com ímpeto naquela casa, e não a pôde abalar, porque estava fundada sobre a rocha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 6, 49, 'Mas aquele que ouve e não pratica é semelhante ao homem que construiu uma casa sobre a terra, sem fundamento, na qual a corrente bateu com ímpeto, e logo caiu; e foi grande a queda daquela casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 1, 'E depois de acabar todos os seus discursos aos ouvidos do povo, ele entrou em Cafarnaum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 2, 'E o servo de um certo centurião, a quem muito estimava, que estava doente, e a ponto de morrer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 3, 'E quando [o centurião] ouviu falar sobre Jesus, enviou-lhe uns anciãos dos judeus, rogando-lhe que viesse curar o seu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 4, 'Eles vieram a Jesus, e rogaram-lhe com urgência, dizendo: Ele é digno de lhe concederes isto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 5, 'porque ele ama a nossa nação, e ele mesmo construiu a nossa sinagoga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 6, 'Jesus foi com eles; mas quando já não estava longe da casa, o centurião enviou-lhe uns amigos, dizendo-lhe: “Senhor, não te incomodes, porque não sou digno que entres abaixo do meu telhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 7, 'Por isso que nem mesmo me considerei digno de vir a ti; mas diz uma palavra, e o meu servo sarará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 8, 'Porque também eu sou homem subordinado à autoridade, e tenho soldados sob o meu comando, e digo a este: ''Vai'', e ele vai; e a outro: ''Vem'', e ele vem; e a meu servo: ''Faz isto'', e ele faz”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 9, 'Quando Jesus ouviu isso, admirou-se dele; então se virou, e disse à multidão que o seguia: Digo-vos que nem mesmo em Israel achei tanta fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 10, 'E quando os que foram enviados voltaram para casa, acharam com boa saúde o servo antes doente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 11, 'E aconteceu no dia seguinte, que [Jesus] ia a uma cidade chamada Naim, e com ele iam muitos de seus discípulos e uma grande multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 12, 'E quando chegou perto da porta da cidade, eis que levavam um defunto, filho único de sua mãe, que [era] viúva; e com ela [ia] grande multidão da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 13, 'Quando o Senhor a viu, comoveu-se de intima compaixão por ela, e disse-lhe: Não chores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 14, 'Então se aproximou, tocou o caixão (e os que a levavam, pararam), e disse: Jovem, a ti eu digo: levanta-te.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 15, 'E o defunto se sentou e começou a falar; e ele o entregou à sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 16, 'Todos se encheram de temor, e glorificavam a Deus, dizendo: “Um grande profeta se levantou entre nós, e Deus visitou o seu povo!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 17, 'E essa sua fama correu por toda a Judeia, e por toda a região em redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 18, 'E os discípulos de João lhe anunciaram essas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 19, 'Então João chamou dois de seus discípulos, e os enviou a Jesus, dizendo: “És tu aquele que havia de vir, ou esperamos outro?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 20, 'E quando aqueles homens vieram a ele, disseram: “João Batista nos enviou a ti, dizendo: ''És tu aquele que havia de vir, ou esperamos outro?''”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 21, 'E naquela mesma hora ele curou a muitos de enfermidades, males, e espíritos maus, e a deu vista a muitos cegos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 22, 'E Jesus lhes respondeu: Ide, e anunciai a João as coisas que tendes visto e ouvido: que os cegos veem, os mancos andam, os leprosos são purificados, os surdos ouvem, os mortos ressuscitam, e aos pobres é anunciado o Evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 23, 'E bendito é aquele que não se ofender em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 24, 'E quando os mensageiros de João se foram, [Jesus] começou a dizer às multidões acerca de João: Que saístes para ver no deserto? Alguma cana sacudida pelo vento?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 25, 'Mas que saístes para ver? Um homem vestido de roupas delicadas? Eis que os que [vestem] roupas delicadas e vivem no luxo estão nos palácios reais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 26, 'Mas que saístes para ver? Um profeta? Sim, vos digo, e muito mais que profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 27, 'Este é aquele de quem está escrito: Eis que envio o meu mensageiro adiante de tua face, o qual preparará o teu caminho diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 28, 'Pois eu vos digo, que dentre os nascidos de mulheres, não há profeta maior que João, o Batista; mas o menor no reino dos céus é maior que ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 29, 'E todo o povo e os publicanos ouviram, concordaram que Deus era justo, e foram batizados com o batismo de João.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 30, 'Mas os fariseus e os estudiosos da Lei rejeitaram o conselho de Deus contra si mesmos, e não foram batizados por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 31, 'E o Senhor disse: “A quem, pois, compararei as pessoas desta geração? E a quem são semelhantes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 32, 'São semelhantes às crianças sentadas na praça, que gritam umas às outras: ''Nós vos tocamos flautas, mas não dançastes; nós vos cantamos lamentações, mas não chorastes''.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 33, 'Porque veio João Batista, que não comia pão, nem bebia vinho, e dizeis: ''Ele tem demônio'';'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 34, 'Veio o Filho do homem, que come e bebe, e dizeis: ''Eis um homem comilão e bebedor de vinho, amigo dos publicanos e dos pecadores''.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 35, 'Mas a sabedoria foi considerada justa por todos os seus filhos”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 36, 'E um dos fariseus lhe pediu que comesse com ele; então entrou na casa do fariseu, e sentou-se [à mesa] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 37, 'E eis que uma mulher da cidade, que era pecadora, quando soube que ele estava na casa do fariseu, trouxe um vaso de alabastro de óleo perfumado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 38, 'E estando atrás, aos seus pés, chorando, começou a molhar-lhe os pés com lágrimas; e os enxugava com os cabelos da sua cabeça; e beijava-lhe os pés, e os ungia com o óleo perfumado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 39, 'E quando o fariseu que o havia convidado viu [isso] , falou consigo mesmo: Se ele fosse profeta, saberia quem e qual é a mulher que o toca; porque ela é pecadora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 40, 'E Jesus lhe respondeu: “Simão, tenho uma coisa a te dizer”; e ele disse: “Dize-a, Mestre”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 41, '[Jesus] disse: “Certo credor tinha dois devedores. Um lhe devia quinhentas moedas de prata, e o outro cinquenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 42, 'Como não tinham com que pagar, perdoou-lhes [a dívida] de ambos. Dize, pois, qual deles o amará mais?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 43, 'Simão respondeu: Tenho para mim que aquele a quem mais perdoou. E ele lhe disse: Julgaste corretamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 44, 'Ele se voltou à mulher, e disse a Simão: Vês tu esta mulher? Entrei na tua casa, e não me deste água para os pés; porém esta molhou os meus pés com lágrimas, e os enxugou com os seus cabelos da cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 45, 'Tu não me beijaste; porém esta, desde que entrou, não parou de me beijar os pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 46, 'Não ungiste a minha cabeça com óleo, porém esta ungiu os meus pés com óleo perfumado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 47, 'Por isso te digo, os muitos pecados dela são perdoados, porque muito amou; mas ao que pouco se perdoa, pouco ama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 48, 'E disse a ela: Os teus pecados são perdoados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 49, 'E os que estavam sentados começaram a dizer entre si: Quem é este, que até perdoa pecados?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 7, 50, 'E disse à mulher: A tua fé te salvou; vai em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 1, 'E aconteceu depois disso, que [Jesus] andava de cidade em cidade, e de aldeia em aldeia, pregando e anunciando o evangelho do reino de Deus; e com ele os doze,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 2, 'e algumas mulheres que haviam sido curadas de espíritos malignos e de enfermidades: Maria, chamada Madalena, da qual saíram sete demônios;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 3, 'e Joana, a mulher de Cuza, mordomo de Herodes; e Susana, e muitas outras, que o serviam com seus bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 4, 'E quando se ajuntou uma multidão, e vindo a ele de todas as cidades, disse por parábola:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 5, 'Saiu um semeador a semear sua semente; e quando semeava, caiu uma [parte] junto ao caminho, e foi pisada, e as aves do céu a comeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 6, 'E outra [parte] caiu sobre a pedra; e nascida, secou-se, porque não tinha umidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 7, 'E outra [parte] caiu entre espinhos, e nascendo com ela, os espinhos a sufocaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 8, 'E outra [parte] caiu em boa terra, e nascida, produziu fruto a cem por um. Depois que disse coisas, exclamava: Quem tem ouvidos para ouvir, ouça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 9, 'E os seus discípulos lhe perguntaram: Que parábola é esta?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 10, 'Ele disse: A vós é dado conhecer os mistérios do reino de Deus; mas aos outros por parábolas, para que vendo, não vejam; e ouvindo, não entendam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 11, 'Esta é, pois, a parábola: a semente é a palavra de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 12, 'Os que estão junto ao caminho são os que ouvem; depois vem o diabo, e tira-lhes do coração a palavra, para que não creiam nem se salvem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 13, 'E os que estão sobre a pedra são os que, quando ouvem, recebem a palavra com alegria, mas esses não têm raiz, pois creem por algum tempo, mas no tempo da tentação se desviam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 14, 'E o que caiu entre espinhos são os que ouviram, e indo, sufocam-se com as preocupações, e riquezas, e prazeres da vida, e não produzem bom fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 15, 'E o que caiu em boa terra, estes são os que, ouvindo a palavra, conservam-na num coração honesto e bom, e dão fruto que permanece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 16, 'E ninguém, quando acende uma lâmpada, cobre-a com algum vaso, ou a põe debaixo da cama; em vez disso põe na luminária, para que os que entram vejam a luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 17, 'Porque não há coisa oculta que não venha a se manifestar; nem coisa escondida que não venha a ser conhecida, e chegada à luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 18, 'Portanto, prestai atenção a como ouvis; pois àquele que tiver lhe será dado; e àquele que não tiver, até o que lhe parece ter, dele será tirado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 19, 'E vieram a ele sua mãe e seus irmãos, mas não conseguiam chegar a ele por causa da multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 20, 'E foi-lhe anunciado, dizendo: “Tua mãe e teus irmãos estão fora, e querem te ver”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 21, 'Porém, ele lhes respondeu: “Minha mãe e meus irmãos são aqueles que ouvem a palavra de Deus e a praticam”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 22, 'E aconteceu, num daqueles dias, que [Jesus] entrou em um barco com seus discípulos, e disse-lhes: “Passemos para o outro lado do lago”. E partiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 23, 'E enquanto navegavam, [Jesus] adormeceu; então desceu uma tempestade de vento no lago, e enchiam-se [de água] , e estavam em perigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 24, 'Então se aproximaram dele e o despertaram, dizendo: “Mestre, Mestre, estamos perecendo!” E ele se levantou, repreendeu o vento e as ondas da água; e pararam, e fez-se bonança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 25, 'E disse-lhes: “Onde está a vossa fé?” Mas eles, temendo, admiravam-se, e diziam uns aos outros: “Quem é este, que manda até aos ventos, e à água, e lhe obedecem?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 26, 'E navegaram para a terra dos gadarenos, que é do lado oposto à Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 27, 'E quando ele desceu à terra, veio da cidade ao seu encontro um homem, que havia muito tempo que tinha demônios, e não andava vestido, nem habitava em casa nenhuma, mas sim, nos sepulcros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 28, 'Ele viu Jesus, então exclamou, prostrou-se diante dele, e disse com grande voz: “O que eu tenho contigo, Jesus, Filho do Deus Altíssimo? Rogo-te que não me atormentes.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 29, 'Porque ele havia mandado ao espírito imundo que saísse daquele homem; pois muitas vezes apoderava-se dele. E o mantinham preso com cadeias e grilhões; porém ele quebrava o que lhe prendia, e era conduzido pelo demônio aos desertos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 30, 'E Jesus lhe perguntou: “Qual é teu nome?” E ele disse: “Legião” (porque muitos demônios tinham entrado nele).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 31, 'E rogavam-lhe que não os mandasse ir para o abismo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 32, 'E havia ali uma manada de muitos porcos, que pastavam no monte; e rogaram-lhe que lhes concedesse entrar neles; e ele lhes concedeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 33, 'Os demônios saíram daquele homem e entraram nos porcos; e a manada se lançou de um precipício no lago e se afogou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 34, 'Quando os que cuidavam [dos porcos] viram o que havia acontecido, fugiram; então foram anunciar na cidade e nos campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 35, 'E saíram para ver o acontecido, e vieram até Jesus; e acharam ao homem de quem os demônios tinham saído, vestido e em pleno juízo, sentado aos pés de Jesus; e temeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 36, 'E os que tinham visto contaram-lhes também como aquele endemoninhado havia sido liberto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 37, 'E toda o povo da terra dos gadarenos ao redor lhe rogou que se retirasse deles; porque foram tomados por grande temor. Então ele entrou no barco e voltou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 38, 'E aquele homem, de quem os demônios tinham saído, rogou-lhe para que lhe permitisse estar com ele; mas Jesus o despediu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 39, '“Volta para tua casa, e conta como foram grandes as coisas que Deus te fez”. Ele se foi, e pregou por toda a cidade, como foram grandes as coisas que Jesus lhe tinha feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 40, 'E aconteceu que, quando Jesus voltou, a multidão o recebeu; porque todos o estavam esperando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 41, 'E eis que chegou um homem, cujo nome era Jairo, e era chefe da sinagoga. Então ele se prostrou aos pés de Jesus e rogou-lhe que entrasse em sua casa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 42, 'porque tinha uma filha única, com doze anos de idade, que estava a ponto de morrer. E enquanto ele ia, as multidões o apertavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 43, 'E uma mulher que tinha um fluxo de sangue, havia doze anos, e já tinha gastado todos os seus pertences com médicos, e não pôde ser curada por nenhum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 44, 'Ela se aproximou [de Jesus] por detrás, e tocou a borda de sua roupa; e logo o fluxo de seu sangue parou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 45, 'E Jesus disse: “Quem me tocou?” Enquanto todos negavam, disse Pedro e os que com ele estavam: Mestre, as multidões te apertam e empurram, e dizes: Quem me tocou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 46, 'Jesus disse: “Alguém me tocou, pois sei que poder saiu de mim”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 47, 'Então a mulher, vendo que não podia se esconder, veio tremendo, prostrou-se diante dele, e declarou-lhe diante de todo o povo a causa por que o havia tocado, e como logo havia sarado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 48, 'E ele lhe disse: “Tem bom ânimo, filha; a tua fé te sarou; vai em paz”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 49, 'Estando ele ainda falando, veio um da [casa] do chefe da sinagoga, que lhe disse: “Tua filha já está morta, não incomodes o Mestre.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 50, 'Porém quando Jesus o ouviu, respondeu-lhe: “Não temas; crê somente, e ela será curada”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 51, 'E quando entrou na casa, a ninguém deixou entrar, a não ser a Pedro, Tiago, João, e ao pai e à mãe da menina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 52, 'E todos choravam e lamentavam por ela; mas ele disse: “Não choreis; ela não está morta, mas dorme”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 53, 'E riam dele, porque sabiam que estava morta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 54, 'Porém ele, depois de expulsá-los todos, segurou a mão dela e clamou: “Levanta-te, menina”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 55, 'Então seu espírito voltou, e ela logo se levantou; e [Jesus] mandou que dessem de comer a ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 8, 56, 'E seus pais ficaram maravilhados, mas ele lhes mandou que a ninguém dissessem o que havia acontecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 1, '[Jesus] convocou seus doze discípulos, e lhes deu poder e autoridade sobre todos os demônios, e para curarem enfermidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 2, 'E os enviou para pregar o reino de Deus e para curar os enfermos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 3, 'E disse-lhes: “Não tomeis nada convosco para o caminho: nem vara, nem bolsa, nem pão, nem dinheiro, nem tenhais duas túnicas cada um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 4, 'E em qualquer casa que entrardes, ficai ali, e dali saí.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 5, 'E a todo os que não vos receberem, quando sairdes daquela cidade, sacudi até o pó dos vossos pés, em testemunho contra eles”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 6, 'Então eles partiram, e percorreram todas as aldeias, anunciando o Evangelho, e curando em todos os lugares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 7, 'E o tetrarca Herodes ouvia falar todas as coisas que ele fazia; e estava perplexo, porque alguns diziam que João tinha ressuscitado dos mortos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 8, 'e outros, que Elias havia aparecido; e outros, que algum profeta dos antigos havia ressuscitado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 9, 'E Herodes disse: “A João mandei degolar; quem, pois, é este, de quem tais coisas ouço?” E procurava vê-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 10, 'E quando os apóstolos, voltaram, contaram [a Jesus] todas as coisas que tinham feito. Então ele os tomou consigo, e retirou-se à parte a um lugar deserto de uma cidade chamada Betsaida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 11, 'E quando as multidões souberam, seguiram-no. Ele as recebeu, e lhes falava do Reino de Deus, e curava aos que precisavam de cura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 12, 'E o dia já começava a declinar. Então os doze se aproximaram dele, e lhe disseram: “Despede a multidão, para irem aos lugares e aldeias ao redor, se agasalhem, e achem o que comer; porque aqui estamos em lugar deserto”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 13, 'Mas ele lhes disse: “Dai-lhes vós de comer”. E eles disseram: “Não temos mais que cinco pães e dois peixes; a não ser se formos nós mesmos comprar de comer para todo este povo”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 14, 'Porque havia ali quase cinco mil homens. Então disse aos seus discípulos: “Fazei-os se sentarem em grupos de cinquenta em cinquenta”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 15, 'E assim procederam, fazendo todos se sentarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 16, 'Então ele tomou os cinco pães e os dois peixes e, olhando para o céu, abençoou-os e partiu-os, e os deu a seus discípulos, para [os] porem diante da multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 17, 'E todos comeram, e saciaram-se; e levantaram doze cestos de pedaços que sobraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 18, 'E aconteceu que, quando ele estava orando só, e seus discípulos estavam com ele, que ele lhes perguntou: “Quem as multidões dizem que eu sou?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 19, 'E eles responderam: “[Uns] , João Batista; outros, Elias; e outros, que algum dos profetas antigos ressuscitou”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 20, 'E disse-lhes: “E vós, quem dizeis que eu sou?” E Pedro respondeu: “O Cristo de Deus”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 21, 'Então ele os alertou, e mandou-lhes que não dissessem a ninguém,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 22, 'dizendo: “É necessário que o Filho do homem sofra muitas coisas; que seja rejeitado pelos anciãos, pelos chefes dos sacerdotes, e pelos escribas; que seja morto, e que seja ressuscitado ao terceiro dia”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 23, 'E dizia a todos: “Se alguém quer vir após mim, negue-se a si mesmo, tome cada dia sua cruz, e siga- me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 24, 'Pois quem quiser salvar sua vida a perderá; porém quem, por minha causa, perder a sua vida, esse a salvará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 25, 'Porque, que aproveita para alguém ganhar o mundo todo, e perder ou prejudicar a si mesmo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 26, 'Pois quem se envergonhar de mim e das minhas palavras, dele o Filho do homem se envergonhará, quando vier na sua glória, e na do Pai, e dos santos anjos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 27, 'E em verdade vos digo que, dentre os que aqui estão, há alguns que não experimentarão a morte, até que vejam o Reino de Deus”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 28, 'E aconteceu que, quase oito dias depois dessas palavras, ele tomou consigo a Pedro, João, e a Jacó, e subiu ao monte para orar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 29, 'E ele, enquanto estava orando, a aparência do seu rosto se transfigurou, e sua roupa [ficou] branca e brilhante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 30, 'E eis que estavam falando com ele dois homens, que eram Moisés e Elias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 31, 'os quais apareceram com glória, e falavam de sua partida, que estava para se cumprir em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 32, 'Pedro e os que estavam com ele estavam cheios de sono; e quando despertaram, viram a glória dele, e aqueles dois homens que estavam com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 33, 'E aconteceu que, quando eles estavam saíndo da presença dele, Pedro disse a Jesus: “Mestre, é bom estarmos nós aqui. Façamos três tendas, uma para ti, uma para Moisés, e uma para Elias”, não sabendo o que dizia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 34, 'E enquanto ele dizia isso, veio uma nuvem que os cobriu com a sua sombra; e, quando entraram na nuvem, temeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 35, 'E veio uma voz da nuvem, que dizia: “Este é o meu Filho amado; a ele ouvi”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 36, 'E, depois de terminada aquela voz, Jesus se encontrava só; e eles se calaram, e por aqueles dias não contaram a ninguém nada do que tinham visto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 37, 'E aconteceu no dia seguinte que, descendo eles do monte, uma grande multidão lhe saiu ao encontro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 38, 'E eis que um homem da multidão clamou: “Mestre, rogo-te que vejas a meu filho, que é o único que tenho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 39, 'e eis que um espírito o toma, e de repente grita, e o convulsiona até espumar, e somente sai dele quando o maltrata severamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 40, 'E roguei aos teus discípulos que o exupulsassem, mas não conseguiram”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 41, 'E Jesus respondeu: “Ó geração incrédula e perversa! Até quando estarei ainda convosco, e vos suportarei? Traze aqui teu filho”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 42, 'E quando ainda vinha chegando, o demônio o derrubou, e o convulsionou. Porém Jesus repreendeu o espírito imundo, curou ao menino, e o devolveu ao seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 43, 'E todos ficaram perplexos com a grandeza de Deus. E enquanto todos se maravilhavam de tudo o que Jesus fazia, disse aos seus discípulos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 44, '“Ponde vós em vossos ouvidos estas palavras: que o Filho do homem será entregue nas mãos dos homens”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 45, 'Mas eles não entendiam essa palavra, e era-lhes encoberta, para que não a compreendessem; e temiam perguntar-lhe sobre essa palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 46, 'E levantou-se entre eles uma discussão sobre qual deles seria o maior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 47, 'Mas Jesus, conhecendo o pensamento de seus corações, pegou uma criança, e a pôs junto a si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 48, 'Então disse-lhes: “Quem receber esta criança em meu nome, a mim me recebe; e quem receber a mim, recebe o que me enviou; porque aquele que entre todos vós for o menor, esse será grande”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 49, 'João respondeu: “Mestre, vimos um que em teu nome expulsava os demônios, e nós o proibimos, porque não segue conosco”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 50, 'E Jesus lhe disse: “Não o proibais, porque quem não é contra nós, é por nós”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 51, 'E aconteceu que, quando completaram-se os dias em que ele viria a ser recebido no alto, ele se determinou a ir para Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 52, 'E mandou mensageiros adiante de si; e eles se foram, e entraram numa aldeia de samaritanos, para lhe fazerem os preparativos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 53, 'Mas não o receberam, porque seu rosto demonstrava que ele ia para Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 54, 'Quando seus discípulos, Tiago e João, viram [isso] , disseram: “Senhor, queres que digamos que desça fogo do céu e os consuma, como Elias também fez?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 55, 'Porém ele se virou, repreendeu-os, e disse: Vós não sabeis de que espírito sois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 56, 'Porque o Filho do homem não veio para destruir as almas dos seres humanos, mas sim para salvá-las.E foram para outra aldeia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 57, 'E aconteceu que, enquanto eles iam pelo caminho, alguém lhe disse: “Senhor, eu te seguirei para onde quer que fores”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 58, 'E Jesus lhe disse: “As raposas têm tocas, e as aves do céu, ninhos; mas o Filho do homem não tem onde deitar a cabeça”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 59, 'E disse a outro: “Segue-me”. Porém ele disse: “Senhor, deixa-me que primeiro eu vá, e eu enterre meu pai”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 60, 'Mas Jesus lhe disse: “Deixa os mortos enterrarem os seus próprios mortos; tu, porém, vai, e anuncia o reino de Deus”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 61, 'E outro também disse: “Senhor, eu te seguirei; mas deixa-me primeiro despedir dos que estão em minha casa”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 9, 62, 'E Jesus lhe disse: “Ninguém que colocar a sua mão no arado e olhar para trás é apto para o reino de Deus”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 1, 'E depois disso, o Senhor ordenou ainda outros setenta, e os mandou de dois em dois adiante de sua face, para toda cidade e lugar aonde ele havia de vir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 2, 'E lhes dizia: “A colheita verdadeiramente é grande, mas os trabalhadores são poucos; portanto rogai ao Senhor da colheita para que ele envie trabalhadores para a sua colheita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 3, 'Ide; eis que eu vos mando como cordeiros no meio dos lobos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 4, 'Não leveis bolsa, nem sacola, nem sandálias; e a ninguém saudeis pelo caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 5, 'E em qualquer casa que entrardes, dizei primeiro: Paz [seja] nesta casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 6, 'E se ali houver algum filho da paz, a vossa paz repousará sobre ele; e se não, ela voltará para vós mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 7, 'E ficai na mesma casa, comendo e bebendo do que eles vos derem; pois o trabalhador é digno do seu salário. Não vos mudeis de casa em casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 8, 'E em qualquer cidade que entrardes, e vos receberem, comei do que puserem diante de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 9, 'E curai os enfermos que nela houver, e dizei-lhes: Chegado é para vós o reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 10, 'Mas em qualquer cidade em que entrardes e não vos receberem, saí pelas ruas, e dizei:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 11, 'Até o pó da vossa cidade que ficou em nós, sacudimos sobre vós; porém disto sabeis, que o reino de Deus é chegado até vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 12, 'E eu vos digo, que mais tolerável será naquele dia para Sodoma, do que para aquela cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 13, 'Ai de ti, Corazim! Ai de ti, Betsaida! Porque se em Tiro e em Sidom tivessem sido feitas as maravilhas que foram feitas entre vós, há muito tempo que teriam se arrependido em saco e em cinza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 14, 'Portanto, para Tiro e Sidom será mais tolerável no juízo, do que para vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 15, 'E tu, Cafarnaum, que [pensas ] estar elevada ao céu, até o Xeol serás derrubada!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 16, 'Quem vos ouve, ouve a mim; e quem vos rejeita, rejeita a mim; e quem me rejeita, rejeita aquele que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 17, 'E os setenta voltaram com alegria, dizendo: Senhor, até os demônios se sujeitam a nós por teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 18, 'E disse-lhes: Eu vi a Satanás, que caía do céu como um raio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 19, 'Eis que vos dou poder para pisar sobre serpentes e escorpiões, e sobre toda a força do inimigo, e nada vos fará dano nenhum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 20, 'Mas não vos alegreis de que os espíritos se sujeitem a vós; em vez disso, alegrai-vos por vossos nomes estarem escritos nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 21, 'Naquela hora Jesus se alegrou em espírito, e disse: Graças te dou, o Pai, Senhor do céu e da terra; porque tu escondeste estas coisas aos sábios e instruídos, e as revelaste às crianças. Sim, Pai, porque assim lhe agradou diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 22, 'Todas as coisas me foram entregues pelo meu Pai; e ninguém sabe quem é o Filho, a não ser o Pai; nem quem é o Pai, a não ser o Filho, e a quem o Filho o quiser revelar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 23, 'E virando-se para seus discípulos, disse [-lhes] à parte: Bem-aventurados os olhos que veem o que vós vedes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 24, 'Porque vos digo, que muitos profetas e reis desejaram ver o que vós vedes, e não o viram; o ouvir o que vós ouvis, e não o ouviram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 25, 'E eis que um certo estudioso da Lei se levantou, tentando-o, e dizendo: Mestre, o que devo fazer para ter para herdar a vida eterna?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 26, 'E ele lhe disse: O que está escrito na Lei? Como tu [a] lês?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 27, 'E respondendo ele, disse: Amarás ao Senhor teu Deus de todo teu coração, e de toda tua alma, e de todas tuas forças, e de todo teu entendimento; e [amarás] a teu próximo como a ti mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 28, 'E disse-lhe: Respondeste bem; faze isso, e viverás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 29, 'Mas ele, querendo se justificar, disse a Jesus: E quem é o meu próximo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 30, 'E respondendo Jesus, disse: Um homem descia de Jerusalém a Jericó, e foi atacado por assaltantes, que também tiraram suas roupas, espancaram-no, e se foram, deixando-o meio morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 31, 'E por acaso descia um certo sacerdote pelo mesmo caminho, e vendo-o, passou longe [dele] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 32, 'E semelhantemente também um levita, chegando junto a aquele lugar, veio, e vendo-o, passou longe [dele]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 33, 'Porém um certo samaritano, que ia pelo caminho, veio junto a ele, e vendo-o, teve compaixão [dele] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 34, 'E chegando-se, amarrou-lhe [um curativo] nas feridas, pondo-lhe nelas azeite e vinho; e pondo-o sobre o animal que o transportava, levou-o para uma hospedaria, e cuidou dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 35, 'E partindo-se no outro dia, tirou dois dinheiros, e os deu para o hospedeiro; e disse-lhe: Cuide dele; e tudo o que gastares a mais, eu te pagarei quando voltar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 36, 'Quem, pois, destes três te parece que foi o próximo daquele que foi atacado por assaltantes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 37, 'Ele disse: Aquele que agiu tendo misericórdia com ele.Então Jesus lhe disse: Vai, e faze da mesma maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 38, 'E aconteceu que eles, enquanto eles caminhavam, ele entrou em uma aldeia; e uma certa mulher, de nome Marta, o recebeu em sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 39, 'E esta tinha uma irmã, chamada Maria, a qual, sentando-se também aos pés de Jesus, ouvia sua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 40, 'Marta, porém, ficava muito ocupada com muitos serviços; e ela, vindo, disse: Senhor, não te importas que minha irmã me deixe sozinha para servir? Dize a ela, pois, que me ajude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 41, 'E respondendo Jesus, disse-lhe: Marta, Marta, [tu és] preocupada com muitas coisas, e perturbada por elas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 10, 42, 'Mas [somente] uma coisa é necessária. E Maria escolheu a parte boa, a qual não lhe será tirada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 1, 'E aconteceu que ele estava orando em um certo lugar. Quando terminou, lhe disse um de seus discípulos: Senhor, ensina-nos a orar, como João também ensinou a seus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 2, 'E ele lhes disse: Quando orardes, dizei: Pai nosso, que [estás] nos céus, santificado seja o teu nome; venha o teu Reino; seja feita a tua vontade, [assim] na terra como no céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 3, 'Dá-nos cada dia nosso pão diário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 4, 'E perdoa-nos nossos pecados, pois também perdoamos a todo aquele que nos deve. E não nos ponhas em tentação, mas livra-nos do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 5, 'Disse-lhes também: Qual de vós que, tendo um amigo, se for a ele à meia-noite, e lhe disser: Amigo, empresta-me três pães.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 6, 'Porque um amigo meu veio de viagem até mim, e nada tenho para lhe apresentar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 7, 'E ele de dentro, respondendo, disser: Não me perturbe! A porta já está fechada, e meus filhos estão comigo na cama; não posso me levantar para te dar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 8, 'Digo-vos, que ainda que ele não se levante para lhe dar por seu seu amigo, contudo, por sua teimosia ele se levantará, e lhe dará tudo quanto ele precisar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 9, 'E eu vos digo: pedi, e será vos dado; buscai, e achareis; batei, e vos será aberto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 10, 'Porque todo o que pede, recebe; e quem busca, acha; e quem bate, lhe será aberto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 11, 'E que pai, dentre vós, a quem o filho pedir pão, lhe dará uma pedra? Ou, se também [lhe pedir] peixe, no lugar do peixe lhe dará uma serpente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 12, 'Ou se também pedir um ovo, lhe dará um escorpião?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 13, 'Pois se vós, sendo maus, sabeis dar bons presentes para vossos filhos, quanto mais dará [vosso] Pai celestial, o Espírito Santo, a aqueles que lhe pedirem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 14, 'E [Jesus] estava expulsando um demônio, e [este] era mudo. E aconteceu que, saindo o demônio, o mudo falou, e as multidões se maravilharam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 15, 'Porém alguns deles diziam: Ele expulsa aos demônios por Belzebu, príncipe dos demônios!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 16, 'E outros, tentando [-o] ,pediam-lhe um sinal do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 17, 'Mas ele, conhecendo seus pensamentos, disse-lhes: Todo reino dividido contra si mesmo é transformado num vazio, e a casa contra casa cai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 18, 'E se também Satanás está dividido contra si mesmo, como durará o seu reino? Porque dizeis: Por Belzebu ele expulsa aos demônios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 19, 'E se eu expulso aos demônios por Belzebu, por quem os seus filhos expulsam? Portanto eles serão vossos juízes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 20, 'Mas se eu expulso aos demônios pelo dedo de Deus, portanto o Reino de Deus chegou a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 21, 'Quando o valente, armado, guarda seu palácio, seus bens estão em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 22, 'Mas vindo outro mais valente que ele, e vencendo-o, toma [-lhe] toda sua armadura, em que confiava, e reparte seus despojos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 23, 'Quem não é comigo, é contra mim; e quem comigo não ajunta, espalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 24, 'Quando o espírito imundo tem saído da pessoa, ele anda por lugares secos, buscando repouso; e não [o] achando, diz: Voltarei para minha casa, de onde saí.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 25, 'E vindo, acha-a varrida e adornada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 26, 'Então vai, e toma consigo outros sete espíritos piores que ele, e entrando, habitam ali; e as últimas coisas de tal pessoa são piores que as primeiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 27, 'E aconteceu que, dizendo ele estas coisas, uma mulher da multidão, levantando a voz, lhe disse: Bem-aventurado o ventre que te trouxe, e os peitos que mamaste!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 28, 'Mas ele disse: Antes bem-aventurados os que ouvem a palavra de Deus, e a guardam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 29, 'E ajuntando as multidões, começou a dizer: Maligna é esta geração; busca sinal, mas sinal não lhe será dado, a não ser o sinal de Jonas o profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 30, 'Porque como Jonas foi sinal para os ninivitas, assim também será o Filho do homem para esta geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 31, 'A rainha do Sul se levantará em juízo com as pessoas desta geração, e as condenará; pois até dos fins da terra veio para ouvir a sabedoria de Salomão; e eis que mais que Salomão está aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 32, 'Os homens de Nínive se levantarão em juízo com esta geração, e a condenarão; pois com a pregação de Jonas se converteram; e eis que mais que Jonas está aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 33, 'E ninguém, acendendo a lâmpada, [a] põe em [lugar] oculto, nem debaixo da caixa, mas na luminária, para que os que entrarem vejam a luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 34, 'A lâmpada do corpo é o olho. Sendo pois teu olho bom, também todo teu corpo será luminoso; porém se for mau, também [todo] teu corpo será tenebroso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 35, 'Olha pois que a luz que em ti há não sejam trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 36, 'Então se sendo teu corpo todo luminoso, não tendo parte alguma escura, ele todo será iluminado, como quando a lâmpada com [seu] brilho te ilumina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 37, 'E estando ele [ainda] falando, um fariseu lhe rogou que viesse para jantar com ele; e entrando, sentou-se [à mesa] ;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 38, 'E vendo [-o] o fariseu, maravilhou-se de que não tinha se lavado antes de jantar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 39, 'E o Senhor lhe disse: Agora vós, os fariseus, limpais o exterior do copo e do prato; porém vosso interior está cheio de roubo e maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 40, 'Loucos, o que fez o exterior não fez também o interior?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 41, 'Porém daí de esmola o que tendes; e eis que tudo vos será limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 42, 'Mais ai de vós, fariseus, que dizimais a hortelã, e a arruda, e toda hortaliça; e pelo juízo e amor de Deus passais longe. Estas coisas era necessário fazer, e não deixar as outras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 43, 'Ai de vós, fariseus, que amais os primeiros assentos nas sinagogas, e as saudações nas praças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 44, 'Ai de vós, escribas e fariseus, hipócritas, que sois como as sepulturas disfarçadas, e as pessoas que andam sobre elas não sabem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 45, 'E respondendo um dos estudiosos da Lei, disse-lhe: Mestre, quando dizes isto também afrontas a nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 46, 'Porém ele disse: Ai de vós também, estudiosos da Lei, que carregais as pessoas com cargas pesadas para levar, e vós mesmos nem ainda com um de vossos dedos tais cargas tocais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 47, 'Ai de vós, que construís os sepulcros dos profetas, e vossos pais os mataram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 48, 'Bem testemunhais pois, que também consentis nas obras de vossos pais; porque eles os mataram, e vós edificais seus sepulcros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 49, 'Portanto também diz a sabedoria de Deus: Profetas e apóstolos lhes mandarei; e deles a [uns] matarão, e a [outros] lançarão fora;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 50, 'Para que desta geração seja requerido o sangue de todos os profetas, que foi derramado desde a fundação do mundo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 51, 'Desde o sangue de Abel, até o sangue de Zacarias, que foi morto entre o altar e a casa [de Deus] ; assim vos digo, será requerido desta geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 52, 'Ai de vós, estudiosos da Lei, que tomastes a chave do conhecimento; vós mesmos não entrastes, e impedistes aos que estavam entrando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 53, 'E dizendo-lhes estas coisas, os escribas e os fariseus começaram a apertá-lo fortemente, e tentar lhe fazer falar de muitas coisas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 11, 54, 'armando-lhe ciladas, e procurando caçar alguma coisa de sua boca, para o poderem acusar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 1, 'Juntando-se, entretanto, muitos milhares da multidão, tanto que se atropelavam uns aos outros, começou a dizer primeiramente a seus discípulos: Guardai-vos do fermento dos fariseus, que é hipocrisia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 2, 'E nada há encoberto que não haja de ser descoberto; nem oculto que não haja de ser sabido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 3, 'Portanto tudo o que dissestes nas trevas, será ouvido na luz; e o que falastes ao ouvido nos quartos, será pregado sobre os telhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 4, 'E digo-vos, amigos meus, não temais aos que matam o corpo, e depois não têm mais o que possam fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 5, 'Mas eu vos mostrarei a quem deveis temer; temei a aquele, que depois de matar, [também] tem poder para lançar no inferno; sim, a este temei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 6, 'Não se vendem cinco passarinhos por duas pequenas moedas? E nem um deles está esquecido diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 7, 'E até os cabelos de vossa cabeça estão todos contados; não temais, pois; mais valeis vós que muitos passarinhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 8, 'E vos digo que todo aquele que me confessar diante dos seres humanos, também o Filho do homem o confessará diante dos anjos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 9, 'Mas quem me negar diante dos seres humanos será negado diante dos anjos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 10, 'E a todo aquele que disser [alguma] palavra contra o Filho do homem, lhe será perdoado, mas ao que blasfemar contra o Espírito Santo, não lhe será perdoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 11, 'E quando vos trouxerem às sinagogas, aos magistrados e autoridades, não estejais ansiosos, como, ou que, em [vossa] defesa deveis dizer, ou que deveis falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 12, 'Porque na mesma hora o Espírito Santo vos ensinará o que deveis falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 13, 'E um da multidão lhe disse: Mestre, dize a meu irmão que reparta a herança comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 14, 'Mas ele lhe disse: Homem, quem me pôs por juiz, ou repartidor sobre vós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 15, 'E disse-lhes: Olhai, e tomai cuidado com a ganância; porque a vida de alguém não consiste na abundância dos bens que possui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 16, 'E propôs-lhes uma parábola, dizendo: A terra de um homem rico tinha frutificado bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 17, 'E ele questionava a si mesmo, dizendo: Que farei? Porque não tenho onde juntar meus frutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 18, 'E disse: Farei isto: derrubarei meus celeiros, e construirei maiores, e ali juntarei toda esta minha colheita, e estes meus bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 19, 'E direi à minha alma: Alma, muitos bens tens guardados, para muitos anos; descansa, come, bebe, alegra-te!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 20, 'Porém Deus lhe disse: Louco, esta noite te pedirão tua alma; e o que tens preparado, de quem será?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 21, 'Assim [é] o que junta tesouros para si, mas não é rico em Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 22, 'E disse a seus discípulos: Portanto vos digo, não estejais ansiosos por vossa vida, que comereis; nem pelo corpo, que vestireis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 23, 'Mais é a vida que o alimento, e [mais] o corpo que o vestido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 24, 'Considerai os corvos, que nem semeiam, nem ceifam; nem tem armazém, nem celeiro; e Deus os alimenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 25, 'E quem de vós pode, com sua ansiedade, acrescentar um côvado à sua altura?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 26, 'Pois, se não podeis nem mesmo com algo pequeno, por que estais ansiosos com o resto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 27, 'Considerai os lírios, como crescem; não trabalham, nem fiam; e digo-vos, que nem mesmo Salomão, em toda sua glória, [chegou] a se vestir como um deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 28, 'E se assim Deus veste a erva, que hoje está no campo, e amanhá é lançada no forno, quanto mais [vestirá] a vós, homens de pouca fé?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 29, 'Vós, pois, não pergunteis que comereis, ou que bebereis; e não andeis preocupados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 30, 'Porque todas estas coisas, os gentios do mundo as buscam; mas vosso Pai sabe que necessitais destas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 31, 'Mas buscai o Reino de Deus, e todas estas coisas vos serão acrescentadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 32, 'Não temas, ó pequeno rebanho; porque vosso Pai se agradou de dar a vós o Reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 33, 'Vendei o que tendes, e daí esmola. Fazei para vós bolsas que não se envelheçam; tesouro nos céus que nunca se deprecia; onde ladrão não chega, nem a traça destrói.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 34, 'Porque aonde estiver vosso tesouro, ali estará também vosso coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 35, 'Estejam devidamente vestidos vossos quadris, e acesas as lâmpadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 36, 'E sede vós semelhantes às pessoas que esperam a seu senhor quando voltar do casamento; para que quando ele vier, e bater, logo possam lhe abrir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 37, 'Bem-aventurados aqueles servos, os quais, quando o Senhor vier, [os] achar vigiando; em verdade vos digo que ele se vestirá, e os fará se sentarem [à mesa] ,e chegando-se, os servirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 38, 'E ainda que venha à segunda vigília; e [que] venha a terceira vigília, e assim [os] achar, bem-aventurados são tais servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 39, 'Isto, porém, sabei: que se o chefe da casa soubesse à que hora o ladrão viria, ele vigiaria, e não deixaria sua casa sofrer dano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 40, 'Vós, pois, também estejais prontos; porque o Filho do homem virá à hora que não imaginais.')
